{"code":"import json
import pandas as pd

with open("evaluations.json") as f:
    data = json.load(f)

rows = []
for d in data:
    if d["iteration"] in [3, 4, 5, 6, 7, 8]:
        row = {"iter": d["iteration"], "y": d["target_dissimilarity"]}
        for item in d["recipe"]:
            row[item["ingredient"]] = item["fraction"]
        rows.append(row)

df = pd.DataFrame(rows).fillna(0)
print(df[["iter", "y", "soy milk", "tofu", "palm oil", "canola oil", "soy protein isolate", "potato starch", "soy sauce"]])
